//   - prog: CUDA Runtime Compilation program
//   - ptx: Compiled result
//
// Errors:
//   - [ErrInvalidInput]
//   - [ErrInvalidProgram]
//
// The result does not include the C string's terminating NUL.
//
// Wraps nvrtcGetPTX.
func getPTX(prog Program) ([]byte, error) {
	if err := checkLibSym("nvrtcGetPTX"); err != nil {
		return nil, err
	}
	size, err := getPTXSize(prog)
	if err != nil {
		return nil, fmt.Errorf("getptx: get size: %w", err)
	}
	if size == 0 {
		return nil, nil
	}
	buf := make([]byte, size)
	if err := toError(fngetPTX(prog, &buf[0]), "nvrtcGetPTX"); err != nil {
		return nil, fmt.Errorf("getptx: %w", err)
	}
	if size > 0 && buf[size-1] == 0 {
		size--
	}
	return buf[:size], nil
}

